              height: (token.h ?? canvas.grid.size) / canvas.grid.size,
              mechanicalWidth: (token.mechanicalBounds?.width ?? token.w ?? canvas.grid.size) / canvas.grid.size,
              textureScaleX: token.document?.texture?.scaleX ?? 1,
